import json, glob, os, re

base = '/home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/artifacts'

# Collect all JSON files (deduplicated, skip hash suffixes)
patterns = [
    f'{base}/alpha_sweep_a*/data/*5method*.json',
    f'{base}/alpha_sweep_a*/*5method*.json',
    f'{base}/alpha_sweep_a*/data/*leadlag*.json',
    f'{base}/alpha_sweep_a*/*leadlag*.json',
    f'{base}/phase_diagram_t*/data/*5method*.json',
    f'{base}/phase_diagram_t*/*5method*.json',
    f'{base}/phase_diagram_t*/data/*leadlag*.json',
    f'{base}/phase_diagram_t*/*leadlag*.json',
]

hash_re = re.compile(r'_[0-9a-f]{6}\.')  # hash suffix pattern

all_files = set()
for p in patterns:
    for f in glob.glob(p):
        if not hash_re.search(os.path.basename(f)):
            all_files.add(f)

results = []

for fpath in sorted(all_files):
    try:
        with open(fpath) as f:
            data = json.load(f)
    except:
        continue

    # Extract directory name to get alpha and T info
    dirname = fpath.split('/artifacts/')[-1].split('/')[0]

    # Try to find perm_granger_fdr_forward_sig
    def find_key(d, key, depth=0):
        if depth > 5: return None
        if isinstance(d, dict):
            if key in d:
                return d[key]
            for v in d.values():
                r = find_key(v, key, depth+1)
                if r is not None:
                    return r
        elif isinstance(d, list):
            for item in d:
                r = find_key(item, key, depth+1)
                if r is not None:
                    return r
        return None

    pgf = find_key(data, 'perm_granger_fdr_forward_sig')

    # Also look for downstream=mauve indicator
    downstream = find_key(data, 'downstream')
    threshold = find_key(data, 'threshold')
    threshold_onset = find_key(data, 'threshold_onset_3sigma')

    # Check if this is D102 standard
    sig_count = None
    if pgf is not None:
        if isinstance(pgf, dict):
            sig = pgf.get('significant', pgf.get('sig_count', None))
            total = pgf.get('total', pgf.get('n_pairs', 8))
            if sig is not None:
                sig_count = f"{sig}/{total}"
        elif isinstance(pgf, str):
            sig_count = pgf
        elif isinstance(pgf, (int, float)):
            sig_count = f"{int(pgf)}/8"

    results.append({
        'dir': dirname,
        'file': os.path.basename(fpath),
        'perm_granger_fdr_forward_sig': str(pgf)[:100] if pgf is not None else 'NOT_FOUND',
        'sig_count': sig_count,
        'downstream': str(downstream)[:30] if downstream else None,
        'threshold': str(threshold)[:30] if threshold else None,
    })

for r in results:
    print(f"{r['dir']:50s} | {r['file']:35s} | sig={r['sig_count'] or r['perm_granger_fdr_forward_sig'][:40]:10s} | ds={r['downstream']} th={r['threshold']}")
